49	@SuppressWarnings({"UnusedReturnValue", "RedundantCast"})
50	public class DocumentEditFragment extends GsFragmentBase implements TextFormat.TextFormatApplier {
51	    public static final int HISTORY_DELTA = 5000;
52	    public static final String FRAGMENT_TAG = "DocumentEditFragment";
53	    private static final String SAVESTATE_DOCUMENT = "DOCUMENT";
54	    private static final String SAVESTATE_CURSOR_POS = "CURSOR_POS";
55	    public static boolean showPreviewOnBack = false;
56	
57	    public static DocumentEditFragment newInstance(Document document) {
58	        DocumentEditFragment f = new DocumentEditFragment();
59	        Bundle args = new Bundle();
60	        args.putSerializable(DocumentIO.EXTRA_DOCUMENT, document);
61	        f.setArguments(args);
62	        return f;
