204	    private long _lastChangedThreadStart = 0;
205	
206	    @OnTextChanged(value = R.id.document__fragment__edit__highlighting_editor, callback = OnTextChanged.Callback.TEXT_CHANGED)
207	    public void onContentEditValueChanged(CharSequence text) {
208	        if ((_lastChangedThreadStart + HISTORY_DELTA) < System.currentTimeMillis()) {
209	            _lastChangedThreadStart = System.currentTimeMillis();
210	            _hlEditor.postDelayed(() -> {
211	                _document.setContent(text.toString());
212	                Activity activity = getActivity();
213	                if (activity != null && activity instanceof AppCompatActivity) {
214	                    ((AppCompatActivity) activity).supportInvalidateOptionsMenu();
215	                }
216	            }, HISTORY_DELTA);
217	        }
218	        Activity activity = getActivity();
219	        if (activity != null && activity instanceof AppCompatActivity) {
220	            ((AppCompatActivity) activity).supportInvalidateOptionsMenu();
221	        }
222	
223	    }
