225	    @SuppressWarnings({"ConstantConditions", "ResultOfMethodCallIgnored"})
226	    private Document loadDocument() {
227	        AppSettings appSettings = new AppSettings(getActivity().getApplicationContext());
228	        Document document = DocumentIO.loadDocument(getActivity(), getArguments(), _document);
229	        if (document != null){
230	            document.setDoHistory(appSettings.isEditorHistoryEnabled());
231	        }
232	        if (document.getHistory().isEmpty()) {
233	            document.forceAddNextChangeToHistory();
234	            document.addToHistory();
235	        }
236	
237	        return document;
238	    }
