265	            _hlEditor.setTextColor(getResources().getColor(R.color.dark_grey));
266	            fragmentView.findViewById(R.id.document__fragment__edit__textmodule_actions_bar__scrolling_parent)
267	                    .setBackgroundColor(getResources().getColor(R.color.lighter_grey));
268	        }
269	    }
