18	
19	@SuppressWarnings({"WeakerAccess", "UnusedReturnValue", "unused"})
20	public class Document implements Serializable {
21	    private final static int MIN_HISTORY_DELAY = 1500; // [ms]
22	    private final static int MAX_HISTORY_SIZE = 5;
23	
24	    private int _format = TextFormat.FORMAT_UNKNOWN;
25	    private ArrayList<Document> _history = new ArrayList<>();
26	    private File _file = null; // Full filepath (path + filename + extension)
27	    private String _title = "";  // The title of the document. May lead to a rename at save
28	    private String _fileExtension = ""; // Not versioned. folder(path) /  title + ext
