49	    public synchronized static Document fromDocumentToDocument(Document source, Document target) {
50	        target.setDoHistory(false);
51	        target.setFile(source.getFile());
52	        target.setTitle(source.getTitle());
53	        target.setContent(source.getContent());
54	        target.setFormat(source.getFormat());
55	        target.setDoHistory(true);
56	        return target;
57	    }
