import net.gsantner.markor.model.Document;
import net.gsantner.opoc.util.FileUtils;

import java.io.File;
import java.util.UUID;

/**
 * Simulates the UI flow: new note -> type title -> type content -> wait -> press save -> back (pause save)
 */
public class Sim {

    // ---- copy of DocumentIO.normalizeTitleForFilename ----
    public static String normalizeTitleForFilename(Document _document) {
        String name = _document.getTitle();
        try {
            if (name.length() == 0) {
                if (_document.getContent().length() == 0) {
                    return null;
                } else {
                    String contentL1 = _document.getContent().split("\n")[0];
                    if (contentL1.length() < 25) {
                        name = contentL1.substring(0, contentL1.length());
                    } else {
                        name = contentL1.substring(0, 25);
                    }
                }
            }
            name = name.replaceAll("[\\\\/:\"´`'*$?<>\n\r@|#]+", "").trim();
        } catch (Exception ignored) {
        }
        if (name == null || name.isEmpty()) {
            name = "Note " + UUID.randomUUID().toString();
        }
        return name;
    }

    // ---- copy of DocumentIO.saveDocument ----
    public static synchronized boolean saveDocument(Document document, boolean argAllowRename, String currentText) {
        boolean ret;
        String filename = normalizeTitleForFilename(document) + document.getFileExtension();
        document.setDoHistory(true);
        document.setFile(new File(document.getFile().getParentFile(), filename));

        Document documentInitial = document.getInitialVersion();
        if (argAllowRename) {
            if (!document.getFile().equals(documentInitial.getFile())) {
                if (documentInitial.getFile().exists()) {
                    if (FileUtils.renameFile(documentInitial.getFile(), document.getFile())) {
                        for (Document hist : document.getHistory()) {
                            hist.setFile(document.getFile());
                            for (Document hist2 : hist.getHistory()) {
                                hist2.setFile(document.getFile());
                            }
                        }
                    }
                }
            }
        } else {
            document.setFile(documentInitial.getFile());
        }

        System.out.println("   saveDocument: file=" + document.getFile().getName()
                + " initialFile=" + documentInitial.getFile().getName()
                + " initialContent='" + documentInitial.getContent() + "'"
                + " currentText='" + currentText + "'");

        if (!currentText.equals(documentInitial.getContent())) {
            document.forceAddNextChangeToHistory();
            document.setContent(currentText);
            ret = FileUtils.writeFile(document.getFile(), document.getContent());
            System.out.println("   -> WROTE file " + document.getFile().getName() + " ret=" + ret);
        } else {
            ret = true;
            System.out.println("   -> SKIPPED WRITE (content equals initial version content!)");
        }
        return ret;
    }

    static void dump(Document d) {
        System.out.println("   doc: file=" + d.getFile().getName() + " title='" + d.getTitle() + "' content='" + d.getContent()
                + "' pos=" + d.getHistoryPosition() + " histSize=" + d.getHistory().size());
        for (int i = 0; i < d.getHistory().size(); i++) {
            Document h = d.getHistory().get(i);
            System.out.println("        h[" + i + "] file=" + h.getFile().getName() + " title='" + h.getTitle() + "' content='" + h.getContent() + "'");
        }
    }

    static void sleep(long ms) {
        try {
            Thread.sleep(ms);
        } catch (Exception ignored) {
        }
    }

    public static void main(String[] args) throws Exception {
        File dir = new File("/tmp/mysim/notebook");
        deleteRec(dir);
        dir.mkdirs();

        // ---- DocumentIO.loadDocument with EXTRA_PATH_IS_FOLDER = true ----
        Document document = new Document();
        document.setDoHistory(false);
        document.setFileExtension(".md");
        File filePath = new File(dir, "Document-" + UUID.randomUUID().toString() + ".md");
        document.setFile(filePath);
        document.setFormat(TextFormatStub.FORMAT_MARKDOWN);
        document.setDoHistory(true);

        // ---- DocumentEditFragment.loadDocument ----
        document.setDoHistory(true); // history enabled setting
        if (document.getHistory().isEmpty()) {
            document.forceAddNextChangeToHistory();
            document.addToHistory();
        }
        System.out.println("After load:");
        dump(document);

        // ---- user types title (toolbar edittext, char by char) ----
        String title = "MyTitle";
        for (int i = 1; i <= title.length(); i++) {
            document.setTitle(title.substring(0, i));
            sleep(300);
        }
        System.out.println("After typing title:");
        dump(document);

        // ---- user types content in editor; content committed to document after HISTORY_DELTA=5s ----
        String content = "Hello content";
        sleep(1000);
        // delayed runnable fires:
        document.setContent(content);
        System.out.println("After content commit (5s delayed runnable):");
        dump(document);

        // ---- user presses save ----
        System.out.println("PRESS SAVE:");
        saveDocument(document, true, content);
        dump(document);
        System.out.println("   dir listing: " + java.util.Arrays.toString(dir.list()));

        // ---- user presses back -> onPause -> saveDocument ----
        sleep(2000);
        System.out.println("PRESS BACK (onPause save):");
        saveDocument(document, true, content);
        dump(document);
        System.out.println("   dir listing: " + java.util.Arrays.toString(dir.list()));
    }

    static void deleteRec(File f) {
        if (f.isDirectory()) {
            for (File c : f.listFiles()) deleteRec(c);
        }
        f.delete();
    }

    static class TextFormatStub {
        static final int FORMAT_MARKDOWN = 2;
    }
}

