import net.gsantner.markor.model.Document;
import net.gsantner.opoc.util.FileUtils;

import java.io.File;
import java.util.UUID;

/** Simulates the whole UI flow with the editor-history setting on/off */
public class Sim2 {

    static boolean FIXED = Boolean.getBoolean("fixed");

    public static String normalizeTitleForFilename(Document _document) {
        String name = _document.getTitle();
        try {
            if (name.length() == 0) {
                if (_document.getContent().length() == 0) {
                    return null;
                } else {
                    String contentL1 = _document.getContent().split("\n")[0];
                    name = contentL1.substring(0, Math.min(25, contentL1.length()));
                }
            }
            name = name.replaceAll("[\\\\/:\"´`'*$?<>\n\r@|#]+", "").trim();
        } catch (Exception ignored) {
        }
        if (name == null || name.isEmpty()) {
            name = "Note " + UUID.randomUUID().toString();
        }
        return name;
    }

    // ------------- current (buggy) implementation -------------
    public static synchronized boolean saveDocumentOld(Document document, boolean argAllowRename, String currentText) {
        boolean ret;
        String filename = normalizeTitleForFilename(document) + document.getFileExtension();
        document.setDoHistory(true);
        document.setFile(new File(document.getFile().getParentFile(), filename));

        Document documentInitial = document.getInitialVersion();
        if (argAllowRename) {
            if (!document.getFile().equals(documentInitial.getFile())) {
                if (documentInitial.getFile().exists()) {
                    if (FileUtils.renameFile(documentInitial.getFile(), document.getFile())) {
                        for (Document hist : document.getHistory()) {
                            hist.setFile(document.getFile());
                            for (Document hist2 : hist.getHistory()) {
                                hist2.setFile(document.getFile());
                            }
                        }
                    }
                }
            }
        } else {
            document.setFile(documentInitial.getFile());
        }

        System.out.println("      [save] target=" + document.getFile().getName()
                + " initialVersionFile=" + documentInitial.getFile().getName()
                + " initialVersionContent='" + documentInitial.getContent() + "'"
                + " editorText='" + currentText + "'");

        if (!currentText.equals(documentInitial.getContent())) {
            document.forceAddNextChangeToHistory();
            document.setContent(currentText);
            ret = FileUtils.writeFile(document.getFile(), document.getContent());
            System.out.println("      [save] -> wrote " + document.getFile().getName() + " (" + ret + ")");
        } else {
            ret = true;
            System.out.println("      [save] -> NO WRITE (editor text == initial version content)");
        }
        return ret;
    }

    // ------------- proposed fixed implementation -------------
    public static synchronized boolean saveDocumentNew(Document document, boolean argAllowRename, String currentText) {
        final File oldFile = document.getFile();
        final String filename = normalizeTitleForFilename(document) + document.getFileExtension();
        document.setDoHistory(true);
        document.setFile(argAllowRename ? new File(oldFile.getParentFile(), filename) : oldFile);

        if (argAllowRename && !document.getFile().equals(oldFile) && oldFile.exists()) {
            if (FileUtils.renameFile(oldFile, document.getFile())) {
                for (Document hist : document.getHistory()) {
                    hist.setFile(document.getFile());
                    for (Document hist2 : hist.getHistory()) {
                        hist2.setFile(document.getFile());
                    }
                }
            }
        }

        final boolean needsWrite = !document.getFile().exists()
                || !currentText.equals(FileUtils.readTextFileFast(document.getFile()));
        document.forceAddNextChangeToHistory();
        document.setContent(currentText);
        System.out.println("      [save] target=" + document.getFile().getName() + " needsWrite=" + needsWrite);
        return !needsWrite || FileUtils.writeFile(document.getFile(), document.getContent());
    }

    static boolean save(Document d, boolean allowRename, String text) {
        return FIXED ? saveDocumentNew(d, allowRename, text) : saveDocumentOld(d, allowRename, text);
    }

    static void sleep(long ms) {
        try {
            Thread.sleep(ms);
        } catch (Exception ignored) {
        }
    }

    static void deleteRec(File f) {
        if (f.isDirectory()) for (File c : f.listFiles()) deleteRec(c);
        f.delete();
    }

    /** returns files in notebook dir after the flow */
    static void newNoteFlow(boolean historyEnabled, boolean pressSaveButton) {
        File dir = new File(System.getProperty("java.io.tmpdir"), "mysim-notebook");
        deleteRec(dir);
        dir.mkdirs();

        // DocumentIO.loadDocument (EXTRA_PATH_IS_FOLDER=true)
        Document document = new Document();
        document.setDoHistory(false);
        document.setFileExtension(".md");
        document.setFile(new File(dir, "Document-" + UUID.randomUUID() + ".md"));
        document.setDoHistory(true);

        // DocumentEditFragment.loadDocument
        document.setDoHistory(historyEnabled);
        if (document.getHistory().isEmpty()) {
            document.forceAddNextChangeToHistory();
            document.addToHistory();
        }

        String title = "MyTitle";
        String content = "Hello content";
        // user types title in toolbar
        for (int i = 1; i <= title.length(); i++) {
            document.setTitle(title.substring(0, i));
            sleep(120);
        }
        // user types content into editor
        if (pressSaveButton) {
            // waits >5s => delayed runnable commits content into document, save icon enabled
            document.setContent(content);
            System.out.println("   -- press save button --");
            save(document, true, content);
        }
        // back pressed -> fragment.onBackPressed()/onPause -> saveDocument
        sleep(1600);
        System.out.println("   -- back pressed (save) --");
        save(document, true, content);

        String[] files = dir.list();
        System.out.println("   RESULT files=" + java.util.Arrays.toString(files)
                + (files != null && files.length == 1 && files[0].equals("MyTitle.md")
                ? "  OK, content='" + FileUtils.readTextFileFast(new File(dir, "MyTitle.md")) + "'" : "  <<< NOTE NOT CREATED PROPERLY"));
    }

    static void existingNoteFlow(boolean historyEnabled, boolean renameTitle) {
        File dir = new File(System.getProperty("java.io.tmpdir"), "mysim-notebook");
        deleteRec(dir);
        dir.mkdirs();
        File existing = new File(dir, "Old.md");
        FileUtils.writeFile(existing, "old content");

        Document document = new Document();
        document.setDoHistory(false);
        document.setFileExtension(".md");
        document.setTitle("Old");
        document.setContent("old content");
        document.setFile(existing);
        document.setDoHistory(true);

        document.setDoHistory(historyEnabled);
        if (document.getHistory().isEmpty()) {
            document.forceAddNextChangeToHistory();
            document.addToHistory();
        }

        if (renameTitle) {
            document.setTitle("New");
        }
        String content = "old content\nplus edits";
        document.setContent(content);
        System.out.println("   -- press save button --");
        save(document, true, content);
        sleep(1600);
        System.out.println("   -- back pressed (save) --");
        save(document, true, content);
        String[] files = dir.list();
        System.out.println("   RESULT files=" + java.util.Arrays.toString(files));
        for (String f : files) {
            System.out.println("      " + f + " => '" + FileUtils.readTextFileFast(new File(dir, f)) + "'");
        }
    }

    public static void main(String[] args) {
        System.out.println("=== implementation: " + (FIXED ? "FIXED" : "CURRENT") + " ===");
        for (boolean hist : new boolean[]{false, true}) {
            System.out.println("\n## NEW NOTE, history=" + hist + ", save button pressed");
            newNoteFlow(hist, true);
            System.out.println("\n## NEW NOTE, history=" + hist + ", save button NOT pressed");
            newNoteFlow(hist, false);
            System.out.println("\n## EXISTING NOTE, history=" + hist + ", no title change");
            existingNoteFlow(hist, false);
            System.out.println("\n## EXISTING NOTE, history=" + hist + ", title renamed");
            existingNoteFlow(hist, true);
        }
    }
}

