public static synchronized boolean saveDocument(Document document, boolean argAllowRename, String currentText) {
    boolean ret;
    // The file the document is currently stored at (if it was already stored at all)
    final File oldFile = document.getFile();
    final String filename = DocumentIO.normalizeTitleForFilename(document) + document.getFileExtension();
    document.setDoHistory(true);

    // Renaming is only allowed if requested, otherwise keep the file the document lives in
    document.setFile(argAllowRename ? new File(oldFile.getParentFile(), filename) : oldFile);

    if (argAllowRename && !document.getFile().equals(oldFile) && oldFile.exists()) {
        if (FileUtils.renameFile(oldFile, document.getFile())) {
            // Rename succeeded -> Rename everything in history too
            for (Document hist : document.getHistory()) {
                hist.setFile(document.getFile());
                for (Document hist2 : hist.getHistory()) {
                    hist2.setFile(document.getFile());
                }
            }
        }
    }

    // Compare against what is really stored on disk. The in-memory history may not contain
    // the initial (unmodified) version at all - e.g. when the editor history is disabled or
    // when the document was already modified before the first version got recorded. Relying
    // on it made saving silently do nothing and the document got lost.
    final boolean isTextUnchangedOnDisk = document.getFile().exists()
            && currentText.equals(FileUtils.readTextFileFast(document.getFile()));

    document.forceAddNextChangeToHistory();
    document.setContent(currentText);
    ret = isTextUnchangedOnDisk || FileUtils.writeFile(document.getFile(), document.getContent());
    return ret;
}

