import net.gsantner.markor.model.Document;
import net.gsantner.opoc.util.FileUtils;
import java.io.File;
import java.util.UUID;

/** Mirrors the PATCHED DocumentIO.saveDocument and exercises the UI flows */
public class Sim4 {
    static String normalizeTitleForFilename(Document d) { return Sim2.normalizeTitleForFilename(d); }

    public static synchronized boolean saveDocument(Document document, boolean argAllowRename, String currentText) {
        boolean ret;
        final File oldFile = document.getFile();
        final String filename = normalizeTitleForFilename(document) + document.getFileExtension();
        document.setDoHistory(true);
        document.setFile(argAllowRename ? new File(oldFile.getParentFile(), filename) : oldFile);

        if (argAllowRename && !document.getFile().equals(oldFile) && oldFile.exists()) {
            if (FileUtils.renameFile(oldFile, document.getFile())) {
                for (Document hist : document.getHistory()) {
                    hist.setFile(document.getFile());
                    for (Document hist2 : hist.getHistory()) hist2.setFile(document.getFile());
                }
            }
        }

        document.forceAddNextChangeToHistory();
        document.setContent(currentText);

        final File file = document.getFile();
        if (!file.exists()) {
            ret = currentText.isEmpty() || FileUtils.writeFile(file, document.getContent());
        } else {
            ret = currentText.equals(FileUtils.readTextFileFast(file)) || FileUtils.writeFile(file, document.getContent());
        }
        return ret;
    }

    static File dir = new File(System.getProperty("java.io.tmpdir"), "mysim-nb4");
    static void fresh() { Sim2.deleteRec(dir); dir.mkdirs(); }

    static Document newNoteDoc(boolean hist) {
        Document d = new Document();
        d.setDoHistory(false);
        d.setFileExtension(".md");
        d.setFile(new File(dir, "Document-" + UUID.randomUUID() + ".md"));
        d.setDoHistory(hist);
        if (d.getHistory().isEmpty()) { d.forceAddNextChangeToHistory(); d.addToHistory(); }
        return d;
    }

    static void report(String name, String expected) {
        String[] f = dir.list();
        java.util.Arrays.sort(f);
        String actual = java.util.Arrays.toString(f);
        String contents = "";
        for (String x : f) contents += " [" + x + "='" + FileUtils.readTextFileFast(new File(dir,x)) + "']";
        boolean ok = actual.equals(expected);
        System.out.println((ok ? "PASS " : "FAIL ") + name + " -> " + actual + contents + (ok ? "" : "  expected " + expected));
    }

    public static void main(String[] args) throws Exception {
        for (boolean hist : new boolean[]{false, true}) {
            // 1. bug report flow: new note, title+content, wait, press save, back
            fresh();
            Document d = newNoteDoc(hist);
            d.setTitle("MyTitle");
            d.setContent("Hello content");          // delayed runnable commits content
            saveDocument(d, true, "Hello content");  // save button
            Thread.sleep(1600);
            saveDocument(d, true, "Hello content");  // back / onPause
            report("hist=" + hist + " new note + save button", "[MyTitle.md]");

            // 2. new note, no save button press
            fresh();
            d = newNoteDoc(hist);
            d.setTitle("MyTitle");
            saveDocument(d, true, "Hello content");
            report("hist=" + hist + " new note, back only    ", "[MyTitle.md]");

            // 3. new note opened and left untouched -> must not create a file
            fresh();
            d = newNoteDoc(hist);
            saveDocument(d, true, "");
            report("hist=" + hist + " untouched new note     ", "[]");

            // 4. existing note edited
            fresh();
            FileUtils.writeFile(new File(dir, "Old.md"), "old content");
            d = new Document();
            d.setDoHistory(false); d.setFileExtension(".md");
            d.setTitle("Old"); d.setContent("old content"); d.setFile(new File(dir, "Old.md"));
            d.setDoHistory(hist);
            if (d.getHistory().isEmpty()) { d.forceAddNextChangeToHistory(); d.addToHistory(); }
            d.setContent("old content+new");
            saveDocument(d, true, "old content+new");
            Thread.sleep(1600);
            saveDocument(d, true, "old content+new");
            report("hist=" + hist + " existing note edited   ", "[Old.md]");

            // 5. existing note, title renamed
            fresh();
            FileUtils.writeFile(new File(dir, "Old.md"), "old content");
            d = new Document();
            d.setDoHistory(false); d.setFileExtension(".md");
            d.setTitle("Old"); d.setContent("old content"); d.setFile(new File(dir, "Old.md"));
            d.setDoHistory(hist);
            if (d.getHistory().isEmpty()) { d.forceAddNextChangeToHistory(); d.addToHistory(); }
            d.setTitle("Renamed"); d.setContent("old content+new");
            saveDocument(d, true, "old content+new");
            report("hist=" + hist + " existing note renamed  ", "[Renamed.md]");

            // 6. allowRename = false (e.g. ShareInto / todo.txt): filename must stay
            fresh();
