import net.gsantner.markor.model.Document;
import net.gsantner.markor.util.DocumentIO;
import net.gsantner.opoc.util.FileUtils;
import java.io.File;
import java.util.UUID;

/** End-to-end check of the reported bug against the real DocumentIO class */
public class Verify {
    static File dir = new File(System.getProperty("java.io.tmpdir"), "verify-notebook");
    static int fails = 0;

    static void fresh() { del(dir); dir.mkdirs(); }
    static void del(File f) { if (f.isDirectory()) for (File c : f.listFiles()) del(c); f.delete(); }

    static Document newNote(boolean historyEnabled) {
