        d.setDoHistory(historyEnabled);          // AppSettings.isEditorHistoryEnabled() -> default false
        if (d.getHistory().isEmpty()) { d.forceAddNextChangeToHistory(); d.addToHistory(); }
        return d;
    }

    static void check(String name, boolean cond, String info) {
        System.out.println((cond ? "  PASS  " : "  FAIL  ") + name + "   " + info);
        if (!cond) fails++;
    }

    public static void main(String[] a) throws Exception {
