            File f = new File(dir, "MyTitle.md");
            check("note created after pressing save + back", f.isFile() && FileUtils.readTextFileFast(f).equals("Hello content"),
                    java.util.Arrays.toString(dir.list()));

            // ---- Without pressing save (must keep working) ----
            fresh();
            d = newNote(hist);
            d.setTitle("MyTitle");
            DocumentIO.saveDocument(d, true, "Hello content");
            f = new File(dir, "MyTitle.md");
            check("note created with back only            ", f.isFile() && FileUtils.readTextFileFast(f).equals("Hello content"),
                    java.util.Arrays.toString(dir.list()));

            // ---- Editing an existing note ----
            fresh();
            File old = new File(dir, "Old.md");
            FileUtils.writeFile(old, "old content");
            d = new Document();
            d.setDoHistory(false); d.setFileExtension(".md"); d.setTitle("Old"); d.setContent("old content"); d.setFile(old);
            d.setDoHistory(hist);
            if (d.getHistory().isEmpty()) { d.forceAddNextChangeToHistory(); d.addToHistory(); }
            d.setContent("old content + edits");
            DocumentIO.saveDocument(d, true, "old content + edits");
            check("edits to existing note are stored      ", FileUtils.readTextFileFast(old).equals("old content + edits"),
                    "'" + FileUtils.readTextFileFast(old) + "'");

            // ---- Renaming via title ----
            fresh();
            old = new File(dir, "Old.md");
            FileUtils.writeFile(old, "old content");
            d = new Document();
            d.setDoHistory(false); d.setFileExtension(".md"); d.setTitle("Old"); d.setContent("old content"); d.setFile(old);
            d.setDoHistory(hist);
            if (d.getHistory().isEmpty()) { d.forceAddNextChangeToHistory(); d.addToHistory(); }
            d.setTitle("Renamed"); d.setContent("renamed content");
            DocumentIO.saveDocument(d, true, "renamed content");
            File ren = new File(dir, "Renamed.md");
            check("title rename moves the file            ", ren.isFile() && !old.exists() && FileUtils.readTextFileFast(ren).equals("renamed content"),
                    java.util.Arrays.toString(dir.list()));

            // ---- Untouched new note must not create a file ----
            fresh();
            d = newNote(hist);
            DocumentIO.saveDocument(d, true, "");
            check("untouched new note creates no file     ", dir.list().length == 0, java.util.Arrays.toString(dir.list()));

            // ---- allowRename=false keeps the filename (e.g. todo.txt) ----
            fresh();
            File todo = new File(dir, "todo.txt");
            FileUtils.writeFile(todo, "old task");
            d = new Document();
            d.setDoHistory(false); d.setFileExtension(".txt"); d.setTitle("todo"); d.setContent("old task"); d.setFile(todo);
            d.setDoHistory(hist);
            if (d.getHistory().isEmpty()) { d.forceAddNextChangeToHistory(); d.addToHistory(); }
            d.setTitle("different title"); d.setContent("new task");
            DocumentIO.saveDocument(d, false, "new task");
            check("allowRename=false keeps filename       ", todo.isFile() && dir.list().length == 1 && FileUtils.readTextFileFast(todo).equals("new task"),
                    java.util.Arrays.toString(dir.list()));

            // ---- Unchanged document must not be rewritten ----
            fresh();
            old = new File(dir, "Same.md");
            FileUtils.writeFile(old, "unchanged");
            long before = old.lastModified();
            Thread.sleep(1100);
            d = new Document();
            d.setDoHistory(false); d.setFileExtension(".md"); d.setTitle("Same"); d.setContent("unchanged"); d.setFile(old);
            d.setDoHistory(hist);
            DocumentIO.saveDocument(d, true, "unchanged");
            check("unchanged document is not rewritten    ", old.lastModified() == before, "mtime kept=" + (old.lastModified() == before));
        }
        System.out.println(fails == 0 ? "\nALL CHECKS PASSED" : "\n" + fails + " CHECK(S) FAILED");
        System.exit(fails == 0 ? 0 : 1);
    }
}
