package net.gsantner.markor.util;

import net.gsantner.markor.model.Document;
import net.gsantner.opoc.util.FileUtils;

import org.junit.Test;

import java.io.File;
import java.util.UUID;

import static org.assertj.core.api.Assertions.assertThat;

public class DocumentIoTest {

    @Test
    public void saveNewDocumentWhoseContentWasAlreadyAppliedToTheDocument() {
        // The editor applies its text to the document after a delay. Pressing the save button
        // afterwards must still store the document - it got silently dropped before.
        File folder = createFolder();
        Document document = newDocumentIn(folder, false);
        document.setTitle("MyTitle");
        document.setContent("Hello content");

        assertThat(DocumentIO.saveDocument(document, true, "Hello content")).isTrue();

        File expected = new File(folder, "MyTitle.md");
        assertThat(expected.isFile()).isTrue();
        assertThat(FileUtils.readTextFileFast(expected)).isEqualTo("Hello content");

        // Saving again (e.g. on back press) keeps the document stored
        assertThat(DocumentIO.saveDocument(document, true, "Hello content")).isTrue();
        assertThat(expected.isFile()).isTrue();
        assertThat(FileUtils.readTextFileFast(expected)).isEqualTo("Hello content");
    }

    @Test
    public void saveNewDocumentWhoseContentIsOnlyKnownByTheEditor() {
        File folder = createFolder();
        Document document = newDocumentIn(folder, false);
        document.setTitle("MyTitle");

        assertThat(DocumentIO.saveDocument(document, true, "Hello content")).isTrue();
        assertThat(FileUtils.readTextFileFast(new File(folder, "MyTitle.md"))).isEqualTo("Hello content");
    }

    @Test
    public void saveModifiedExistingDocument() {
        File folder = createFolder();
        File file = new File(folder, "Existing.md");
        FileUtils.writeFile(file, "old content");
        Document document = existingDocument(file, false);
        document.setContent("old content + edits");

        assertThat(DocumentIO.saveDocument(document, true, "old content + edits")).isTrue();
        assertThat(FileUtils.readTextFileFast(file)).isEqualTo("old content + edits");
    }

    @Test
    public void saveRenamesFileWhenTitleChanged() {
        File folder = createFolder();
        File file = new File(folder, "Existing.md");
        FileUtils.writeFile(file, "old content");
        Document document = existingDocument(file, false);
        document.setTitle("Renamed");
        document.setContent("new content");

        assertThat(DocumentIO.saveDocument(document, true, "new content")).isTrue();

        File renamed = new File(folder, "Renamed.md");
        assertThat(file.exists()).isFalse();
        assertThat(FileUtils.readTextFileFast(renamed)).isEqualTo("new content");
        assertThat(folder.list()).hasSize(1);
    }

    @Test
    public void saveKeepsFilenameWhenRenameIsNotAllowed() {
        File folder = createFolder();
        File file = new File(folder, "todo.txt");
        FileUtils.writeFile(file, "old task");
        Document document = existingDocument(file, false);
        document.setFileExtension(".txt");
        document.setTitle("some other title");
        document.setContent("new task");

        assertThat(DocumentIO.saveDocument(document, false, "new task")).isTrue();
        assertThat(folder.list()).containsExactly("todo.txt");
        assertThat(FileUtils.readTextFileFast(file)).isEqualTo("new task");
    }

    @Test
    public void saveDoesNotCreateAFileForAnEmptyNewDocument() {
        File folder = createFolder();
        Document document = newDocumentIn(folder, false);

        assertThat(DocumentIO.saveDocument(document, true, "")).isTrue();
        assertThat(folder.list()).isEmpty();
    }

    @Test
    public void saveWithEnabledHistoryStoresDocumentToo() {
        File folder = createFolder();
        Document document = newDocumentIn(folder, true);
        document.setTitle("MyTitle");
        document.setContent("Hello content");

        assertThat(DocumentIO.saveDocument(document, true, "Hello content")).isTrue();
        assertThat(FileUtils.readTextFileFast(new File(folder, "MyTitle.md"))).isEqualTo("Hello content");
    }

    // Like DocumentIO.loadDocument() for a folder + DocumentEditFragment.loadDocument()
    private Document newDocumentIn(File folder, boolean historyEnabled) {
        Document document = new Document();
        document.setDoHistory(false);
        document.setFileExtension(".md");
        document.setFile(new File(folder, "Document-" + UUID.randomUUID().toString() + ".md"));
        return initHistory(document, historyEnabled);
    }

    private Document existingDocument(File file, boolean historyEnabled) {
        Document document = new Document();
        document.setDoHistory(false);
        document.setFileExtension(".md");
        document.setTitle(file.getName().replaceAll("\\.[^.]*$", ""));
        document.setContent(FileUtils.readTextFileFast(file));
        document.setFile(file);
        return initHistory(document, historyEnabled);
    }

    private Document initHistory(Document document, boolean historyEnabled) {
        document.setDoHistory(historyEnabled);
        if (document.getHistory().isEmpty()) {
            document.forceAddNextChangeToHistory();
            document.addToHistory();
        }
        return document;
    }

    @SuppressWarnings("ResultOfMethodCallIgnored")
    private File createFolder() {
        File folder = new File(System.getProperty("java.io.tmpdir"), "markor-test-" + UUID.randomUUID().toString());
        folder.mkdirs();
        folder.deleteOnExit();
        return folder;
    }
}

